def feature(s):
    v = s.get('volume_per_atom_A3')
    if v is None:
        v = s.get('basic_structure_statistics', {}).get('volume_per_atom_A3')
    if v is not None and math.isfinite(v) and v > 0:
        return float(v)
    return 0.0

def feature(s):
    v = s.get('volume_per_atom_A3')
    if v is None:
        v = s.get('basic_structure_statistics', {}).get('volume_per_atom_A3')
    if v is None or not math.isfinite(v) or v <= 0:
        return 0.0
    props = s.get('element_properties', {})
    total = 0.0
    weight = 0.0
    for el, f in s.get('composition', {}).items():
        r = props.get(el, {}).get('covalent_radius_A')
        if f is not None and f > 0 and r is not None and math.isfinite(r) and r > 0:
            total += f * r * r * r
            weight += f
    return float(4.0 * math.pi * total / (3.0 * weight * v)) if weight > 0 else 0.0

def feature(s):
    v = s.get('volume_per_atom_A3')
    if v is None:
        v = s.get('basic_structure_statistics', {}).get('volume_per_atom_A3')
    if v is None or not math.isfinite(v) or v <= 0:
        return 0.0
    props = s.get('element_properties', {})
    total = 0.0
    weight = 0.0
    for el, f in s.get('composition', {}).items():
        z = props.get(el, {}).get('valence_electrons')
        if f is not None and f > 0 and z is not None and math.isfinite(z) and z >= 0:
            total += f * z
            weight += f
    return float(total / (weight * v)) if weight > 0 else 0.0

def feature(s):
    props = s.get('element_properties', {})
    entries = []
    for el, f in s.get('composition', {}).items():
        p = props.get(el, {})
        ie = p.get('first_ionization_energy_eV')
        ea = p.get('electron_affinity_eV')
        if f is not None and math.isfinite(f) and f > 0 and ie is not None and ea is not None and math.isfinite(ie) and math.isfinite(ea) and ie - ea > 1e-6:
            entries += [(f, 0.5 * (ie + ea), ie - ea)]
    total = sum(a[0] for a in entries)
    inverse_hardness = sum(a[0] / a[2] for a in entries)
    if total <= 0 or inverse_hardness <= 0:
        return 0.0
    mu = sum(a[0] * a[1] / a[2] for a in entries) / inverse_hardness
    return float(sum(a[0] * ((mu - a[1]) / a[2]) ** 2 for a in entries) / total)
